import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"20 Claude Opus 4.8 Workflows That Make Money While You Sleep","description":"","frontmatter":{"url":"https://x.com/sairahul1/status/2060646901524156778","title":"20 Claude Opus 4.8 Workflows That Make Money While You Sleep","author":"sairahul1","archived":"2026-05-31T00:00:00.000Z","handle":"@sairahul1","published":"2026-05-30T00:00:00.000Z","stats":"308 likes · 44 retweets · 1070 bookmarks · 525672 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-30-@sairahul1-156778.md","filePath":"research/tweets/2026-05-30-@sairahul1-156778.md","lastUpdated":1780990164000}'),i={name:"research/tweets/2026-05-30-@sairahul1-156778.md"};function n(s,e,l,p,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_20-claude-opus-4-8-workflows-that-make-money-while-you-sleep-—-sairahul1" tabindex="-1">20 Claude Opus 4.8 Workflows That Make Money While You Sleep — @sairahul1 <a class="header-anchor" href="#_20-claude-opus-4-8-workflows-that-make-money-while-you-sleep-—-sairahul1" aria-label="Permalink to &quot;20 Claude Opus 4.8 Workflows That Make Money While You Sleep — @sairahul1&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/sairahul1/status/2060646901524156778" target="_blank" rel="noreferrer">https://x.com/sairahul1/status/2060646901524156778</a><strong>作者</strong>：sairahul1（@sairahul1） <strong>發布日期</strong>：2026-05-30 <strong>收錄日期</strong>：2026-05-31 <strong>類型</strong>：Twitter Article <strong>統計</strong>：308 likes · 44 retweets · 1070 bookmarks · 525672 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Anthropic dropped Opus 4.8 while most of us were sleeping.</p><p>Most people saw &quot;better coding model.&quot;</p><p>The builders who looked closer saw something else entirely.</p><p>Claude can now work toward a defined completion state instead of waiting for your next prompt.</p><p>We just moved from:</p><p>&quot;Write me 10 ad ideas.&quot;</p><p>to</p><p>&quot;Don&#39;t come back until you&#39;ve found the best ad idea in my category.&quot;</p><p>That single shift changes everything about how you use AI to make money.</p><hr><h2 id="what-actually-changed-—-opus-4-8-in-60-seconds" tabindex="-1">WHAT ACTUALLY CHANGED — OPUS 4.8 IN 60 SECONDS <a class="header-anchor" href="#what-actually-changed-—-opus-4-8-in-60-seconds" aria-label="Permalink to &quot;WHAT ACTUALLY CHANGED — OPUS 4.8 IN 60 SECONDS&quot;">​</a></h2><p>Not a full model rewrite. A targeted upgrade that fixes the right things.</p><p>→ 69.2% SWE-bench Pro (up from 64.3% on 4.7) → 4x less likely to miss its own mistakes → Admits uncertainty instead of fabricating answers → Works independently longer without going off track → Same price as before: $5/$25 per million tokens → Fast mode: 2.5x speed, 3x cheaper than before</p><p>But the model upgrade isn&#39;t the story.</p><p>Dynamic Workflows is the story.</p><hr><h2 id="what-dynamic-workflows-actually-are" tabindex="-1">WHAT DYNAMIC WORKFLOWS ACTUALLY ARE <a class="header-anchor" href="#what-dynamic-workflows-actually-are" aria-label="Permalink to &quot;WHAT DYNAMIC WORKFLOWS ACTUALLY ARE&quot;">​</a></h2><p>One agent working step by step is the old way.</p><p>Dynamic Workflows is different.</p><p>You describe a goal. Claude writes its own orchestration script. Hundreds of parallel subagents spin up. They work simultaneously. They verify each other&#39;s work adversarially - agents actively try to break each other&#39;s findings. Results combine into one answer before anything reaches you.</p><p>You come back to finished work. Not a draft. Not a half-done task. A completed output that Claude verified before handing back.</p><p>The proof that this is real:</p><blockquote><p>Jarred Sumner used Dynamic Workflows to rewrite Bun from Zig to Rust. 750,000 lines of Rust. 99.8% of the existing test suite passing. 11 days from first commit to merge. Hundreds of agents working in parallel with two reviewers on each file. Work that engineering teams plan in quarters finished in days.</p></blockquote><p>How to trigger it:</p><p>→ Need Claude Code v2.1.154 or later → Max, Team, or Enterprise plan → Type &quot;workflow&quot; in your prompt — Claude plans and confirms before running → OR set /effort ultracode — Claude decides automatically when to trigger it → Turn on auto mode first: /permissions → select auto mode</p><p>Token warning: Dynamic Workflows use significantly more tokens than a normal session. Start with a scoped task. Use /cost to monitor usage.</p><hr><h2 id="the-shift-nobody-is-talking-about" tabindex="-1">THE SHIFT NOBODY IS TALKING ABOUT <a class="header-anchor" href="#the-shift-nobody-is-talking-about" aria-label="Permalink to &quot;THE SHIFT NOBODY IS TALKING ABOUT&quot;">​</a></h2><p>Before Dynamic Workflows, every AI task ended the same way.</p><p>Claude finished. Stopped. Waited for you.</p><p>You reviewed. Decided what was missing. Prompted again. Reviewed again.</p><p>You were the loop.</p><p>Dynamic Workflows removes you from the loop.</p><p>You define the completion state — what &quot;done&quot; actually looks like — and Claude runs until it gets there. Verifying its own work. Catching its own mistakes. Iterating until the answer converges.</p><p>The founders who learn to define completion states instead of just prompts are about to gain a significant advantage over everyone still doing it one prompt at a time.</p><p>Here are 20 completion states worth setting tonight.</p><hr><h2 id="making-money" tabindex="-1">MAKING MONEY <a class="header-anchor" href="#making-money" aria-label="Permalink to &quot;MAKING MONEY&quot;">​</a></h2><ol><li>Google Maps Lead Generation — 200 Businesses, One Prompt</li></ol><p>Old way: research one business, write one brief, repeat for weeks.</p><p>New way:</p><blockquote><p>Create a workflow to search Google Maps in [city] for [niche — HVAC, plumbers, dentists, roofers]. Find 200 businesses with ratings above 4.0 but no website or an outdated one. For each business: pull their services, their best reviews, their contact details, and their trust signals. Generate a complete outreach brief and website mockup brief for every single one. Don&#39;t stop until all 200 are done.</p></blockquote><p>You wake up to 200 qualified leads with personalized briefs ready to send.</p><p>Close 5% at $800 average = $8,000 from one overnight prompt.</p><hr><ol start="2"><li>Cold Email Sequences — Personalized for Every Prospect</li></ol><p>Generic emails get deleted.</p><blockquote><p>Create a workflow to write personalized cold email sequences for every business in this list [attach CSV]. For each one: research their specific situation, identify the exact problem my product solves for them, write a 3-email sequence personalized to their company. Don&#39;t use templates. Each email should reference something specific about that business. Don&#39;t stop until every prospect has a complete sequence.</p></blockquote><p>500 personalized sequences. Ready to send. While you slept.</p><hr><ol start="3"><li>Competitor Pricing Intelligence — Full Market Map</li></ol><blockquote><p>Create a workflow to research every competitor in [your market]. For each one: find their current pricing, their positioning, their main offer, their weakest reviews, and the gaps in what they provide. Build a complete competitive intelligence report with a clear map of where I can undercut, differentiate, or own a position they&#39;re missing. Don&#39;t stop until you&#39;ve covered every major player.</p></blockquote><p>The output: a complete market map with specific gaps to exploit.</p><hr><ol start="4"><li>Affiliate Content Machine — 30 Articles in One Run</li></ol><blockquote><p>Create a workflow to research and write 30 SEO-optimized articles for [affiliate niche]. For each article: find the target keyword, research the top 5 ranking pages, identify what they&#39;re missing, and write a complete article that covers those gaps. Each article should be 1,200-1,500 words. Include internal linking suggestions between articles. Don&#39;t stop until all 30 are complete and verified for quality.</p></blockquote><p>30 articles. Overnight. Ready to publish.</p><hr><ol start="5"><li>Pricing Page Optimization — Find the Revenue You&#39;re Leaving Behind</li></ol><blockquote><p>Create a workflow to audit my onboarding funnel and pricing page. Research the top 20 companies in my category and analyze their pricing structure, anchoring strategy, and conversion elements. Cross-reference with 100 pricing psychology studies. Then audit my current page against all findings. Don&#39;t stop until you&#39;ve identified every specific change that would increase conversion — with the evidence for each one.</p></blockquote><p>The output: a prioritized list of changes with conversion impact estimates.</p><hr><h2 id="marketing-and-growth" tabindex="-1">MARKETING AND GROWTH <a class="header-anchor" href="#marketing-and-growth" aria-label="Permalink to &quot;MARKETING AND GROWTH&quot;">​</a></h2><ol start="6"><li>Find 100 Viral Hooks — Don&#39;t Stop Until You Have Them</li></ol><blockquote><p>Create a workflow to find 100 viral hooks for content about [your topic]. Search for the top-performing posts in this niche across Twitter, LinkedIn, and YouTube. Analyze what makes each one work — the emotional trigger, the format, the specific language pattern. Then generate 100 hooks using those exact patterns, categorized by type. Don&#39;t stop until you have 100 hooks with documented evidence of why each one should work.</p></blockquote><p>Not 10 hooks you have to guess about. 100 hooks reverse-engineered from what already went viral.</p><hr><ol start="7"><li>Ad Account Audit — Categorize Every Winner</li></ol><blockquote><p>Create a workflow to analyze every ad in my account [attach export]. Categorize every ad by: belief being challenged, emotional angle, format type, offer framing, and hook structure. Identify the patterns in the top 20% of performers. Find what the bottom 20% have in common. Build a complete creative brief for the next 10 ads based on what the data actually shows. Don&#39;t stop until every ad is categorized and the brief is complete.</p></blockquote><p>You stop guessing what works in your ads. The data tells you.</p><hr><ol start="8"><li>5,000 App Store Reviews — Every Insight Extracted</li></ol><blockquote><p>Create a workflow to analyze every review of [app name] on the App Store and Google Play. Cluster every objection, desire, feature request, and compliment by theme. Find the exact language customers use to describe their problems. Identify the top 5 reasons people leave and the top 5 reasons people stay. Don&#39;t stop until every review is processed and the insights are ranked by frequency and impact.</p></blockquote><p>The output replaces a $10,000 user research project.</p><hr><ol start="9"><li>Onboarding Funnel Investigation</li></ol><blockquote><p>Create a workflow to audit my onboarding funnel from signup to first value moment. Research the best onboarding flows in my category. Map every step in my current flow. Identify every drop-off point. For each drop-off: find 3 specific fixes that similar companies have used successfully. Don&#39;t stop investigating until you&#39;ve found the single biggest conversion bottleneck and documented exactly how to fix it.</p></blockquote><p>One overnight run. The biggest revenue leak in your product identified and fixed.</p><hr><ol start="10"><li>Top 20 Competitor Messaging Matrix</li></ol><blockquote><p>Create a workflow to research my top 20 competitors. For each one: analyze their homepage, their ads, their top content, and their customer reviews. Build a complete messaging matrix comparing: core positioning, primary hook, main offer, proof points, and CTAs. Then identify the messaging gap — the position none of them own that I could. Don&#39;t stop until all 20 are analyzed and the matrix is complete.</p></blockquote><p>The positioning gap your competitors left open. Found overnight.</p><hr><h2 id="content" tabindex="-1">CONTENT <a class="header-anchor" href="#content" aria-label="Permalink to &quot;CONTENT&quot;">​</a></h2><ol start="11"><li>50 UGC Concepts — Every Awareness Stage Covered</li></ol><blockquote><p>Create a workflow to generate 50 UGC video concepts for [product]. Cover every awareness stage: completely unaware, problem aware, solution aware, product aware, and most aware. For each stage generate 10 concepts with: hook, core message, format, and call to action. Don&#39;t stop until all 50 are complete with documented reasoning for why each one fits that awareness stage.</p></blockquote><p>A full UGC content calendar. One run.</p><hr><ol start="12"><li>Scan Every Landing Page in Your Category</li></ol><blockquote><p>Create a workflow to find and analyze every landing page in [your category]. For each page: identify the headline structure, the proof elements, the offer framing, and the CTA. Find the patterns that appear in the highest-converting pages. Find what the lowest-converting pages have in common. Build a conversion pattern report with specific recommendations for my landing page. Don&#39;t stop until you&#39;ve covered at least 50 pages.</p></blockquote><p>The highest-converting patterns in your market. Documented. Overnight.</p><hr><ol start="13"><li>30-Day Content Calendar — Researched and Drafted</li></ol><blockquote><p>Create a workflow to build a complete 30-day content calendar for [platform] in [niche]. For each day: research what&#39;s currently performing in this niche, identify the angle with the highest engagement potential, write a complete post draft. Include hook, body, and CTA for every post. Don&#39;t stop until all 30 days are drafted and every post has been checked against current top performers in the niche.</p></blockquote><p>A month of content. One overnight run.</p><hr><ol start="14"><li>YouTube Script Package — 10 Videos Ready to Record</li></ol><blockquote><p>Create a workflow to research and write 10 complete YouTube scripts for [channel topic]. For each video: find a topic with proven search demand and engagement, research the top competing videos and what they&#39;re missing, write a complete word-for-word script with hook, open loop, body, and CTA. Include thumbnail concept and title variations for each. Don&#39;t stop until all 10 scripts are complete and verified against top performers.</p></blockquote><p>10 videos. Researched, scripted, and ready to record.</p><hr><ol start="15"><li>Newsletter Issue — Fully Researched and Written</li></ol><blockquote><p>Create a workflow to research and write a complete newsletter issue about [topic]. Search for every major development in this space from the last 7 days. Find the 5 most important stories. For each story: verify across multiple sources, extract the key insight for my audience, and write a 200-word section. Write a complete introduction and conclusion. Don&#39;t stop until the full issue is written and every fact is verified.</p></blockquote><p>A fully researched newsletter. Written and verified. While you slept.</p><hr><h2 id="research-and-strategy" tabindex="-1">RESEARCH AND STRATEGY <a class="header-anchor" href="#research-and-strategy" aria-label="Permalink to &quot;RESEARCH AND STRATEGY&quot;">​</a></h2><ol start="16"><li>Market Research Report — 100 Sources, One Document</li></ol><blockquote><p>Create a workflow to produce a complete market research report for [market]. Research the market size, growth rate, key players, customer segments, and emerging trends. Synthesize findings from at least 100 sources. Verify every statistic against its original source. Flag any conflicting data. Don&#39;t stop until the report is complete with a full source list and every claim verified.</p></blockquote><p>A $5,000 market research report. One prompt. One night.</p><hr><ol start="17"><li>Investment or Partnership Due Diligence</li></ol><blockquote><p>Create a workflow to conduct due diligence on [company]. Research their founding team, funding history, product, customer reviews, press coverage, and competitive position. Find every red flag and every positive signal. Cross-reference claims against independent sources. Build a complete due diligence report with a clear recommendation. Don&#39;t stop until every major question is answered and documented.</p></blockquote><p>The research that normally takes a team two weeks. Done overnight.</p><hr><ol start="18"><li>Pricing Strategy — Full Analysis</li></ol><blockquote><p>Create a workflow to build a complete pricing strategy for [product]. Research how every major competitor prices their product. Find every pricing psychology study relevant to my category. Analyze my current pricing against customer willingness to pay signals in reviews and support tickets [attach]. Build 3 complete pricing models with projected revenue impact for each. Don&#39;t stop until all 3 models are fully built and stress-tested.</p></blockquote><p>Three pricing models. With projected revenue impact. Ready to decide from.</p><hr><ol start="19"><li>SEO Opportunity Map — Every Gap in Your Market</li></ol><blockquote><p>Create a workflow to find every SEO content gap in [niche]. Research the top 50 keywords in this space. For each keyword: analyze the top 10 ranking pages, identify what they&#39;re missing, and assess the realistic difficulty of ranking. Find the 20 keywords where I can rank in under 6 months with quality content. Don&#39;t stop until every opportunity is documented with difficulty score and content brief.</p></blockquote><p>20 SEO opportunities with content briefs. One overnight run.</p><hr><ol start="20"><li>Business Idea Validation — Full Market Test</li></ol><blockquote><p>Create a workflow to validate [business idea]. Research: market size, existing competitors, customer pain points from forums and reviews, willingness to pay signals, regulatory considerations, and distribution channels. Find 50 potential customers and analyze what they&#39;re currently paying for alternatives. Build a complete validation report with a clear go/no-go recommendation. Don&#39;t stop until every major assumption is tested.</p></blockquote><p>Full validation of a business idea. Before you spend a dollar building it.</p><hr><h2 id="the-pattern-across-all-20" tabindex="-1">THE PATTERN ACROSS ALL 20 <a class="header-anchor" href="#the-pattern-across-all-20" aria-label="Permalink to &quot;THE PATTERN ACROSS ALL 20&quot;">​</a></h2><p>Look at every prompt above.</p><p>They all end the same way.</p><p>&quot;Don&#39;t stop until.&quot;</p><p>That&#39;s the unlock.</p><p>You&#39;re not asking Claude to do a task anymore.</p><p>You&#39;re giving it a completion state and letting it run until it gets there.</p><p>The agents work in parallel. They verify each other&#39;s findings. They iterate until the answers converge. You come back to finished work.</p><p>Before Dynamic Workflows: you were the loop between every AI task. After Dynamic Workflows: Claude closes the loop itself.</p><p>That&#39;s the shift.</p><p>The founders who figure out how to define completion states — not just write prompts — are about to pull ahead of everyone still doing it one message at a time.</p><hr><h2 id="how-to-start-tonight" tabindex="-1">HOW TO START TONIGHT <a class="header-anchor" href="#how-to-start-tonight" aria-label="Permalink to &quot;HOW TO START TONIGHT&quot;">​</a></h2><p>You need:</p><p>→ Claude Code v2.1.154 or later (claude update) → Max ($100/month), Team, or Enterprise plan → Auto mode on: run /permissions → select auto mode</p><p>Pick one prompt from the list above.</p><p>Start scoped — not your entire business, one specific task.</p><p>Use /cost to monitor token usage as it runs.</p><p>The first workflow will feel slow.</p><p>By the third one you&#39;ll wonder how you ever worked without it.</p><hr><p>If this was useful: → Repost so other builders see it → Follow @sairahul1 for more systems that run without you → Bookmark this - the 20 prompts are worth keeping</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Opus 4.8 Dynamic Workflows 的關鍵是從「命令式 prompt」升級為「宣告式 completion state」（Don&#39;t stop until...），搭配平行 subagent + 對抗性驗證，提供 20 個可直接套用的 workflow prompt 模板。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>範式轉移</strong>：從「寫 10 個廣告想法」→「找出最佳廣告想法後才停下」，是 prompt 到 completion state 的根本升級</li><li><strong>Dynamic Workflows 機制</strong>：Claude 自動撰寫 orchestration script，啟動數百個平行 subagent，互相對抗性驗證，只回傳完成品</li><li><strong>觸發方式</strong>：Claude Code v2.1.154+、Max/Team/Enterprise plan、<code>/permissions</code> auto mode 或 <code>/effort ultracode</code></li><li><strong>&quot;Don&#39;t stop until&quot; 語法</strong>：是讓 Dynamic Workflows 自動運行的核心 termination condition</li><li><strong>20 個實戰模板</strong>：分 4 類（賺錢/行銷成長/內容/研究策略），每個都含具體完成條件</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><strong>Opus 4.8 效能</strong>：69.2% SWE-bench Pro（vs 4.7 的 64.3%）、4x 更少遺漏錯誤</li><li><strong>Fast mode</strong>：2.5x 速度，3x 便宜</li><li><strong>定價</strong>：$5/$25 per million tokens（input/output）；Max plan $100/month</li><li><strong>Bun rewrite 案例</strong>：750,000 行 Rust，99.8% test pass，11 天（Jarred Sumner）</li><li><strong>觸發關鍵字</strong>：prompt 中輸入 &quot;workflow&quot;，或 <code>/effort ultracode</code></li><li><strong>20 個完整 completion state prompt</strong>（lead gen / cold email / competitor intel / SEO / UGC / due diligence 等）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>Dynamic Workflows 描述有行銷誇大成分</strong>：「數百個平行 subagent 互相對抗」聽起來很強，但 Anthropic 官方文件描述較保守；Bun 案例是真實的，但屬極端工程案例，不代表一般 workflow 的效果</li><li><strong>部分 workflow 存在操作限制</strong>：Google Maps scraping（服務條款限制）、5000 App Store 評論分析（需 API 或爬蟲）等在 Claude Code 沙盒環境中有實際執行門檻，非一個 prompt 就能完成</li><li><strong>completion state 框架本身有價值</strong>：從命令式到宣告式是真實的 LLM 使用升級，&quot;Don&#39;t stop until&quot; 語法可立即套用；但要區分「有幫助的框架」與「夜賺萬元的行銷聲明」</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>20 個完整 prompt 模板可直接複製使用；completion state 語法立即可採用</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>&quot;completion state vs prompt&quot; 框架有洞察；Dynamic Workflows 功能真實存在，但包裝偏行銷</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>Bun rewrite 是真實案例，但 ROI 數字（8000/night）純屬估算，20 個 workflow 無執行驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>觸發條件具體，但 Dynamic Workflows 內部機制描述（orchestration script、adversarial verification）缺乏技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>completion state 概念和 20 個模板可泛化到各種業務、研究、內容場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.6/10</strong></td><td>7×0.3+6×0.2+6×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：20 個 completion state prompt 模板是靜態可重用的 prompt 方法論；&quot;Don&#39;t stop until&quot; 語法直接可整合到現有 workflow skill 中。</p>',164)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
